package agent

import (
	_ "embed"
	"encoding/json"
	"sort"
	"strings"
	"sync"

	"campfire/internal/proto"
)

// worldgen_catalog.json is generated by tools/gen_worldgen_catalog.py from the
// game's own scripts (customize.lua + chinese_s.po), so the panel always shows
// exactly the settings this game build supports.
//
//go:embed worldgen_catalog.json
var worldgenCatalogJSON []byte

type catalogFile struct {
	Groups    []catalogGroup    `json:"groups"`
	Playstyles []catalogPlaystyle `json:"playstyles"`
}

type catalogGroup struct {
	Name     string           `json:"name"`
	Kind     string           `json:"kind"`
	Settings []catalogSetting `json:"settings"`
}

type catalogSetting struct {
	Key              string        `json:"key"`
	Label            string        `json:"label"`
	Hover            string        `json:"hover"`
	Default          string        `json:"default"`
	Worlds           []string      `json:"worlds"`
	Choices          []catalogChoice `json:"choices"`
	MasterControlled bool          `json:"master_controlled"`
}

type catalogChoice struct {
	Label string `json:"label"`
	Value string `json:"value"`
}

type catalogPlaystyle struct {
	ID       string            `json:"id"`
	Name     string            `json:"name"`
	Preset   string            `json:"preset"`
	Desc     string            `json:"desc"`
	Overrides map[string]string `json:"overrides"`
}

var (
	catalogOnce sync.Once
	catalogVal  proto.WorldgenCatalog
)

// worldgenCatalogData returns the embedded world-settings catalog.
func worldgenCatalogData() proto.WorldgenCatalog {
	catalogOnce.Do(func() {
		var f catalogFile
		if err := json.Unmarshal(worldgenCatalogJSON, &f); err != nil {
			catalogVal = proto.WorldgenCatalog{}
			return
		}
		cat := proto.WorldgenCatalog{}
		for _, g := range f.Groups {
			pg := proto.WorldgenGroup{Name: g.Name, Kind: g.Kind}
			for _, s := range g.Settings {
				ps := proto.WorldgenSetting{
					Key:              s.Key,
					Label:            s.Label,
					Hover:            s.Hover,
					Default:          s.Default,
					Worlds:           s.Worlds,
					MasterControlled: s.MasterControlled,
				}
				ps.Scope, ps.Phase, ps.Shards = settingScope(g.Kind, s.Worlds)
				for _, c := range s.Choices {
					ps.Choices = append(ps.Choices, proto.ModChoice{Label: c.Label, Value: c.Value})
				}
				pg.Settings = append(pg.Settings, ps)
			}
			cat.Groups = append(cat.Groups, pg)
		}
		for _, p := range f.Playstyles {
			cat.Playstyles = append(cat.Playstyles, proto.Playstyle{
				ID: p.ID, Name: p.Name, Preset: p.Preset, Desc: p.Desc, Overrides: p.Overrides,
			})
		}
		cat.Presets = worldPresets()
		catalogVal = cat
	})
	return catalogVal
}

// worldPresets lists the settings presets a new world can start from.
func worldPresets() []proto.Preset {
	master := []proto.Preset{
		{ID: "SURVIVAL_TOGETHER", Name: "标准生存"},
		{ID: "SURVIVAL_TOGETHER_CLASSIC", Name: "经典生存"},
		{ID: "SURVIVAL_DEFAULT_PLUS", Name: "生存（更多）"},
		{ID: "TERRARIA", Name: "泰拉瑞亚"},
	}
	caves := []proto.Preset{
		{ID: "DST_CAVE", Name: "标准洞穴", Cave: true},
		{ID: "DST_CAVE_PLUS", Name: "洞穴（更多）", Cave: true},
		{ID: "TERRARIA_CAVE", Name: "泰拉瑞亚洞穴", Cave: true},
	}
	return append(master, caves...)
}

// presetName returns the display name of a preset id.
func presetName(id string) string {
	if id == "" {
		return "默认"
	}
	for _, p := range worldPresets() {
		if p.ID == id {
			return p.Name
		}
	}
	return id
}

// sortedGroupNames is used by the frontend fallback ordering (kept simple).
func sortedGroupNames(cat proto.WorldgenCatalog) []string {
	var names []string
	for _, g := range cat.Groups {
		names = append(names, g.Name)
	}
	sort.Strings(names)
	return names
}

// settingScope 依据游戏 customize.lua 的 world 字段，解析一个设置项属于哪个分片、
// 属于"世界生成"还是"世界规则"：
//
//	world = {"forest"}         → forest（只在地上页出现）
//	world = {"cave"}           → cave（只在洞穴页出现）
//	world = {"forest","cave"}  → both（两页都出现，各写各的）
//	没有 world 字段（全局规则） → global：由森林/地上分片主控，运行时自动同步到洞穴，
//	                              所以只在"地上世界"页显示，洞穴页不出现
//
// kind == "worldgen" 的项是生成阶段一次性读取的（生成后锁定）；kind == "settings"
// 的项是运行时规则，随时可改。
func settingScope(kind string, worlds []string) (scope, phase string, shards []string) {
	phase = "rules"
	if kind == "worldgen" {
		phase = "generation"
	}
	hasForest, hasCave := false, false
	for _, w := range worlds {
		switch strings.ToLower(strings.TrimSpace(w)) {
		case "forest":
			hasForest = true
		case "cave":
			hasCave = true
		}
	}
	switch {
	case hasForest && hasCave:
		return "both", phase, []string{"forest", "cave"}
	case hasCave:
		return "cave", phase, []string{"cave"}
	case hasForest:
		return "forest", phase, []string{"forest"}
	default:
		return "global", phase, []string{"forest"}
	}
}

// shardWorldName maps a shard name to the customize.lua world name.
func shardWorldName(shard string) string {
	if shardIsCaves(shard) {
		return "cave"
	}
	return "forest"
}

// settingApplies reports whether the setting can be written into the shard's
// worldgenoverride.lua at all.
func settingApplies(s proto.WorldgenSetting, shard string) bool {
	w := shardWorldName(shard)
	for _, x := range s.Shards {
		if x == w {
			return true
		}
	}
	return false
}

// catalogSettingByKey finds a setting in the embedded catalog.
func catalogSettingByKey(key string) (proto.WorldgenSetting, bool) {
	cat := worldgenCatalogData()
	for _, g := range cat.Groups {
		for _, s := range g.Settings {
			if s.Key == key {
				return s, true
			}
		}
	}
	return proto.WorldgenSetting{}, false
}

// filterOverridesForShard drops settings that do not belong to the shard — e.g. a
// forest-only rule (野火/季节/火狗) accidentally written into the caves shard, or
// a cave-only rule into the overworld — and returns the keys it dropped.
//
// 未知键一律保留：模组设置、以及以后游戏新增的选项，不能因为面板不认识就丢掉。
func filterOverridesForShard(shard string, overrides map[string]string) (map[string]string, []string) {
	if len(overrides) == 0 {
		return overrides, nil
	}
	out := make(map[string]string, len(overrides))
	var dropped []string
	for k, v := range overrides {
		if s, ok := catalogSettingByKey(k); ok && !settingApplies(s, shard) {
			dropped = append(dropped, k)
			continue
		}
		out[k] = v
	}
	sort.Strings(dropped)
	return out, dropped
}
